import { useEffect, useState, useCallback } from 'react';
import { useDispatch } from 'react-redux';
import socketService from '../services/socket';
import { setConnectionStatus } from '../store/slices/uiSlice';

export const useSocket = () => {
  const [socket, setSocket] = useState(null);
  const [isConnected, setIsConnected] = useState(false);
  const dispatch = useDispatch();

  // Initialize socket connection
  useEffect(() => {
    const initSocket = () => {
      const socketInstance = socketService.connect();
      setSocket(socketInstance);

      // Set up connection status listener
      socketService.on('connection-status', (data) => {
        const { status } = data;
        setIsConnected(status === 'connected' || status === 'reconnected');
        dispatch(setConnectionStatus(status));
      });

      return socketInstance;
    };

    const socketInstance = initSocket();

    // Cleanup on unmount
    return () => {
      if (socketInstance) {
        socketService.disconnect();
        setSocket(null);
        setIsConnected(false);
      }
    };
  }, [dispatch]);

  // Join session room
  const joinSession = useCallback((sessionId) => {
    if (socket && isConnected) {
      socketService.joinSession(sessionId);
    }
  }, [socket, isConnected]);

  // Subscribe to stock updates
  const subscribeToStock = useCallback((productId) => {
    if (socket && isConnected) {
      socketService.subscribeToStock(productId);
    }
  }, [socket, isConnected]);

  // Unsubscribe from stock updates
  const unsubscribeFromStock = useCallback((productId) => {
    if (socket && isConnected) {
      socketService.unsubscribeFromStock(productId);
    }
  }, [socket, isConnected]);

  // Emit event
  const emit = useCallback((event, data) => {
    if (socket && isConnected) {
      socketService.emit(event, data);
    }
  }, [socket, isConnected]);

  // Listen to events
  const on = useCallback((event, callback) => {
    if (socket) {
      socketService.on(event, callback);
    }
  }, [socket]);

  // Remove event listener
  const off = useCallback((event, callback) => {
    if (socket) {
      socketService.off(event, callback);
    }
  }, [socket]);

  return {
    socket,
    isConnected,
    joinSession,
    subscribeToStock,
    unsubscribeFromStock,
    emit,
    on,
    off,
  };
};
